<div class="card">	<div class="card-header d-md-flex justify-content-between align-items-center">		<h4 class="card-title">Thông tin</h4>		<div class="header-right mt-md-0 mt-50">			<a class="btn btn-success mb-1" href="<?php echo base_url($module_slug); ?>"><i class="bx bx-table"></i>&nbsp;Danh sách</a>		</div>	</div>	<div class="card-content">		<div class="card-body">			<div class="box-body">				<form id="f-content" action="<?php echo base_url($module_slug . '/them'); ?>" method="post" autocomplete="off" enctype="multipart/form-data">					<?php					if (isset($row['id'])) {						echo '<input type="hidden" value="' . $row['id'] . '" id="id" name="id" class="form-control" />';					}					?>					<div class="row">						<div class="col-md-12">							<div class="form-group required<?php echo form_error('name') != '' ? ' has-error' : ''; ?>">								<label for="name" class="control-label">Tên <?php echo $module_name; ?></label>								<input type="text" maxlength="255" value="<?php echo isset($row['name']) ? $row['name'] : ''; ?>" name="name" id="name" class="form-control">								<?php echo form_error('name'); ?>							</div>						</div>					</div>					<div class="text-center">						<?php if (isset($row['id'])) : ?>							<input class="btn btn-primary" type="submit" value="Lưu thay đổi">						<?php else : ?>							<input class="btn btn-success" type="submit" value="Đăng <?php echo $module_name; ?>">						<?php endif; ?>					</div>				</form>			</div>		</div>	</div></div>